        ctx.fillStyle=focused?(spec.stripe||palette.light||'#5ce5e8'):'#ffffff';ctx.fillRect(x+5,y+4,w-10,2);
        const contentTop=y+8,contentBottom=y+h-3,cy=(contentTop+contentBottom)/2;
