      ctx.fillStyle = "#e0a742"; ctx.fillRect(141,160,18,4); ctx.fillRect(151,151,3,14);
      ctx.fillStyle = "#73b8db"; ctx.fillRect(161,156,18,5); ctx.fillRect(165,149,3,13);
      ctx.fillStyle = "#2c819f"; ctx.fillRect(181,177,24,13);
