      const active = focused || hovered;
      ctx.fillStyle = "rgba(25,43,52,0.30)";
      ctx.fillRect(button.x + 2, button.y + 2, button.w, button.h);
      ctx.fillStyle = active ? getSelectedSkin().dark : COLORS.ink;
